"""One-page PDF summary of a single risk assessment."""

from datetime import datetime
from io import BytesIO

from fpdf import FPDF

from heart.config import FEATURE_LABELS, FEATURES
from heart.predict import Prediction, display_value
from heart.schemas import PatientInput

DISCLAIMER = (
    "For education and research only. This report is generated by a statistical model trained "
    "on 303 patients from a single 1988 study. It is not a medical device and must not be used "
    "for diagnosis or treatment decisions. Consult a qualified clinician."
)


def _ascii(text: str) -> str:
    """Core PDF fonts are Latin-1 only."""
    return (
        text.replace("≥", ">=")
        .replace("≤", "<=")
        .replace("±", "+/-")
        .replace("–", "-")
        .encode("latin-1", "replace")
        .decode("latin-1")
    )


def build_pdf_report(
    patient: PatientInput,
    prediction: Prediction,
    waterfall_png: bytes | None = None,
    generated_at: datetime | None = None,
) -> bytes:
    generated_at = generated_at or datetime.now()
    pdf = FPDF(format="A4")
    pdf.set_auto_page_break(auto=True, margin=15)
    pdf.add_page()
    width = pdf.epw

    pdf.set_font("Helvetica", "B", 18)
    pdf.cell(width, 10, "Heart Disease Risk Assessment", new_x="LMARGIN", new_y="NEXT")
    pdf.set_font("Helvetica", "", 9)
    pdf.set_text_color(100)
    pdf.cell(
        width,
        5,
        _ascii(
            f"Generated {generated_at:%Y-%m-%d %H:%M} | model {prediction.model_name} "
            f"v{prediction.model_version}"
        ),
        new_x="LMARGIN",
        new_y="NEXT",
    )
    pdf.set_text_color(0)
    pdf.ln(4)

    # Result
    pdf.set_font("Helvetica", "B", 13)
    pdf.cell(width, 8, "Result", new_x="LMARGIN", new_y="NEXT")
    pdf.set_font("Helvetica", "", 11)
    screen = "Positive" if prediction.has_disease else "Negative"
    for label, value in [
        ("Estimated probability", f"{prediction.probability:.0%}"),
        ("Risk band", prediction.risk_band),
        ("Screening result", f"{screen} (threshold {prediction.threshold:.0%})"),
        ("Average training patient", f"{prediction.base_probability:.0%}"),
    ]:
        pdf.cell(60, 7, label)
        pdf.set_font("Helvetica", "B", 11)
        pdf.cell(width - 60, 7, _ascii(value), new_x="LMARGIN", new_y="NEXT")
        pdf.set_font("Helvetica", "", 11)
    pdf.ln(3)

    # Inputs
    pdf.set_font("Helvetica", "B", 13)
    pdf.cell(width, 8, "Clinical inputs", new_x="LMARGIN", new_y="NEXT")
    pdf.set_font("Helvetica", "", 10)
    values = patient.model_dump()
    with pdf.table(col_widths=(2, 1), text_align=("LEFT", "LEFT"), line_height=6) as table:
        header = table.row()
        header.cell("Measurement")
        header.cell("Value")
        for feature in FEATURES:
            row = table.row()
            row.cell(_ascii(FEATURE_LABELS[feature]))
            row.cell(_ascii(display_value(feature, float(values[feature]))))
    pdf.ln(4)

    # Explanation
    if prediction.contributions:
        pdf.set_font("Helvetica", "B", 13)
        pdf.cell(width, 8, "Main factors (SHAP)", new_x="LMARGIN", new_y="NEXT")
        pdf.set_font("Helvetica", "", 10)
        for c in prediction.contributions[:5]:
            direction = "raises" if c.shap_value > 0 else "lowers"
            pdf.multi_cell(
                width,
                6,
                _ascii(
                    f"- {c.label} = {c.display_value}: {direction} the estimate by "
                    f"{abs(c.shap_value):.0%} points"
                ),
                new_x="LMARGIN",
                new_y="NEXT",
            )
        if waterfall_png:
            pdf.ln(2)
            pdf.image(BytesIO(waterfall_png), w=width * 0.85)
        pdf.ln(3)

    pdf.set_font("Helvetica", "I", 8)
    pdf.set_text_color(120)
    pdf.multi_cell(width, 4, _ascii(DISCLAIMER))
    return bytes(pdf.output())
